input.command:
cd /tmp; t(){ echo "--- $*"; sudo -n "$@" 2>&1; echo "rc=$?"; }
C=/usr/sbin/chroot
t $C / /bin/echo hi; t $C --skip-chdir / /bin/pwd; t $C / /bin/pwd; t $C --userspec=nobody:nogroup --groups=1,2 / /usr/bin/id; t $C --userspec=65534 / /usr/bin/id; t $C --userspec=:65534 / /usr/bin/id; t $C --groups=   / /usr/bin/id; t $C --groups=nosuch / /usr/bin/id; t $C --userspec=nosuchuser / /usr/bin/id; t $C / /bin/nonexistent; t $C / /etc/passwd; echo hello | sudo -n $C / /bin/cat; echo "rc=$?"; t $C --skip-chdir /tmp /bin/true; t $C / /bin/sh -c 'exit 7'; t $C / -- /bin/echo dashdash; t $C -- / /bin/echo dashdash2; t $C / --skip-chdir; echo 'echo via stdin shell' | sudo -n env SHELL=/bin/sh $C /; echo rc=$?; t $C /etc/passwd /bin/true
